	awk := exec.Command("awk", `BEGIN {OFS=","} {print $1,$2,$3-$6-$7,$4+$6+$7}`)

	out, err := memory.StdoutPipe()
	if err != nil {
		log.Fatal(err)
	}
	memory.Start()
	awk.Stdin = out

	mem_out, err := awk.Output()
	if err != nil {
		log.Fatal(err)
	}
	return string(mem_out), nil
}

