	sylCnt := float64(CntSyls(text))
	wordCnt := float64(CntWords(text))
	sentCnt := float64(CntSents(text))	
	return 206.835 - 1.015*(wordCnt/sentCnt) - 84.6*(sylCnt/wordCnt)
}

