	r := gin.Default()
	r.GET("/", func(c *gin.Context) {

		str := c.DefaultQuery("str", "")
		len := c.DefaultQuery("len", "0")
		ch := c.DefaultQuery("ch", " ")

		lenInt, err := strconv.Atoi(len)

		if err != nil {
			lenInt = 0
		}

		c.JSON(200, gin.H{
			"str": leftPad(str, ch, lenInt),
		})
	})
	r.Run(":3000")
}

