func IsCgroup2UnifiedMode() (bool, error) {
	isUnifiedOnce.Do(func() {
		_cgroup2SuperMagic := int64(0x63677270)
		var st syscall.Statfs_t
		if err := syscall.Statfs("/sys/fs/cgroup", &st); err != nil {
