			}
		}
	}
	if image.ReleaseNotes != nil && image.ReleaseNotes.Object != nil {
		hashes = append(hashes, *image.ReleaseNotes.Object)
	}
	if image.BuildLog != nil && image.BuildLog.Object != nil {
		hashes = append(hashes, *image.BuildLog.Object)
	}
	return hashes
}

