func write(out chan int, i int) {

	defer func() {
		// recover from panic caused by writing to a closed channel
		if err := recover(); err != nil {
			fmt.Printf("write: error writing %d on channel: %v\n", i, err)
			return
		}

		fmt.Printf("write: wrote %d on channel\n", i)
	}()

