	out, err := os.Create(fmt.Sprintf("backup-%d", transfer.Num))
	if err != nil {
		return nil, err
	}

	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	n, err := io.Copy(out, resp.Body)
	if err != nil {
		return nil, err
	}
	log.Printf("Copied %d bytes", n)

	return out, nil
}

